/*
 * XrHeader: small application header carried at the start of every UDP payload
 * generated by XrTrafficApp.
 *
 * Layout (16 bytes, network byte order):
 *   uint32  frameId   index of the application frame (ADU)
 *   uint16  fragIdx   index of this fragment inside the frame (0 based)
 *   uint16  nFrags    total number of fragments of the frame
 *   uint64  txTimeNs  time the frame was handed to the socket [ns]
 *
 * Purpose: lets a receiver compute per packet and per frame delay and
 * reassemble frames (needed later for frame level QoS metrics).
 */
#ifndef XR_HEADER_H
#define XR_HEADER_H

#include "ns3/header.h"
#include "ns3/nstime.h"

namespace ns3
{

class XrHeader : public Header
{
  public:
    static TypeId GetTypeId();
    TypeId GetInstanceTypeId() const override;

    XrHeader();

    void SetFrameId(uint32_t id);
    uint32_t GetFrameId() const;

    void SetFragIdx(uint16_t idx);
    uint16_t GetFragIdx() const;

    void SetNFrags(uint16_t n);
    uint16_t GetNFrags() const;

    void SetTxTime(Time t);
    Time GetTxTime() const;

    uint32_t GetSerializedSize() const override;
    void Serialize(Buffer::Iterator start) const override;
    uint32_t Deserialize(Buffer::Iterator start) override;
    void Print(std::ostream& os) const override;

    static constexpr uint32_t SIZE = 16; //!< serialized size in bytes

  private:
    uint32_t m_frameId{0};
    uint16_t m_fragIdx{0};
    uint16_t m_nFrags{1};
    uint64_t m_txTimeNs{0};
};

} // namespace ns3

#endif // XR_HEADER_H